messages.content:
IMAGE correct_badge "成功01-1" x=120 y=420 w=160 h=160 z=50 vis=true
MOVE correct_badge 320 220 ms=600 keep=true
STYLE correct_badge {"scale":1.3,"alpha":0.85}

IMAGE ambient_env "草地背景" animation={"loop":{"animId":"呼吸","duration":1800}} x=0 y=0 w=800 h=600 z=0 vis=true
STYLE ambient_env {"alpha":0.82,"scale":1}
WAIT 1800

IMAGE score_change_hint count-1 style={"alpha":0.55} x=360 y=80 w=80 h=80 z=50 vis=true
STYLE score_change_hint {"scale":1.4,"alpha":1}
ANIM_IN score_change_hint bounce ms=450

IMAGE sync_pill "粉色药片" style={"alpha":0.55} x=120 y=360 w=90 h=90 z=20 vis=true
MOVE sync_pill 400 220 ms=600 keep=true
STYLE sync_pill {"scale":1.25,"alpha":1,"zIndex":30}

IMAGE timer_clock "时钟组件" x=360 y=40 w=80 h=80 z=50 vis=true
STYLE timer_clock {"scale":1.2,"alpha":0.9}
ANIM_LOOP timer_clock pulse ms=700

IMAGE bug-battle-hint "触摸指导01" x=700 y=500 w=45 h=43 z=20 vis=true
STYLE bug-battle-hint {"alpha":0.8,"scale":1.2}
ANIM_IN bug-battle-hint scaleIn ms=350

IMAGE asparagus "莴笋" x=200 y=150 vis=true
STYLE asparagus {"tint":"#ff0000","alpha":1}
ANIM_IN asparagus scaleIn ms=350
IMAGE plate "盘子" x=400 y=150 vis=true
STYLE plate {"tint":"#00ff00","alpha":1}
ANIM_IN plate scaleIn ms=350
